# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(render(shape(intake(sift(digest(raw))))))

